        inline static void scale_configuration(Configuration &q) noexcept
        {
            q = q * Configuration(s_m) + Configuration(s_a);
        }

        inline static void descale_configuration(Configuration &q) noexcept
        {
            q = (q - Configuration(s_a)) * Configuration(d_m);
        }

        inline static auto normalize_configuration(Configuration q) noexcept -> Configuration
        {
            auto values = q.to_array();
            for (const auto index : periodic_indices)
            {
                values[index] = std::atan2(std::sin(values[index]), std::cos(values[index]));
            }
            return Configuration(values.data());
        }

        inline static auto difference(const Configuration &from, const Configuration &to) noexcept
            -> Configuration
        {
            auto delta = to - from;
            auto values = delta.to_array();
            for (const auto index : periodic_indices)
            {
                values[index] = std::atan2(std::sin(values[index]), std::cos(values[index]));
            }
            return Configuration(values.data());
        }

        inline static auto distance(const Configuration &from, const Configuration &to) noexcept -> float
        {
            return difference(from, to).l2_norm();
        }

        inline static auto
        interpolate(const Configuration &from, const Configuration &to, float alpha) noexcept -> Configuration
        {
            return normalize_configuration(from + difference(from, to) * alpha);
        }

